public class CustomerWithOrdersExtractor
    implements ResultSetExtractor<List<CustomerWithOrders>> {

  @Override
  public List<CustomerWithOrders> extractData(ResultSet resultSet) throws SQLException {
    Map<Long, CustomerWithOrders> byCustomerId = new LinkedHashMap<>();
    while (resultSet.next()) {                          // YOU control the loop
      long customerId = resultSet.getLong("customer_id");
      CustomerWithOrders customer = byCustomerId.get(customerId);
      if (customer == null) {
        customer = new CustomerWithOrders(customerId, resultSet.getString("customer_name"));
        byCustomerId.put(customerId, customer);
      }
      customer.addOrder(resultSet.getLong("order_id"), resultSet.getBigDecimal("total"));
    }
    return new ArrayList<>(byCustomerId.values());
  }
}

