public interface CustomerRepository extends JpaRepository<Customer, Long> {

  // 1. Derived query: Spring writes the SQL from the method name
  List<Customer> findByLastNameAndActiveTrue(String lastName);

  // 2. @Query with a named parameter
  @Query("select c from Customer c where c.email = :email")
  Optional<Customer> findByEmailAddress(@Param("email") String email);

  // 3. Native SQL
  @Query(value = "select * from customers where created_at > :since", nativeQuery = true)
  List<Customer> findCreatedSince(@Param("since") LocalDate since);

  // 4. Changing data needs @Modifying
  @Modifying
  @Query("update Customer c set c.active = false where c.lastLogin < :cutoff")
  int deactivateInactiveSince(@Param("cutoff") LocalDate cutoff);
}

